use std::cmp::Reverse;
use std::collections::BinaryHeap;

fn merge_feeds(mut feeds: Vec<Option<Box<ListNode>>>) -> Option<Box<ListNode>> {
    // The heap holds (head value, feed index). BinaryHeap is a max-heap, so
    // Reverse turns it into a min-heap. The nodes themselves stay in `feeds`.
    let mut heap = BinaryHeap::new();
    for (i, feed) in feeds.iter().enumerate() {
        if let Some(node) = feed {
            heap.push(Reverse((node.val, i)));
        }
    }
    let mut out = None;
    let mut tail = &mut out;
    while let Some(Reverse((_, i))) = heap.pop() {
        let mut node = feeds[i].take().unwrap();
        feeds[i] = node.next.take();
        if let Some(next) = &feeds[i] {
            heap.push(Reverse((next.val, i)));
        }
        tail = &mut tail.insert(node).next;
    }
    out
}

