class ListNode:
    def __init__(self, val: int = 0, next: "ListNode | None" = None):
        self.val = val
        self.next = next


def merge_two(a: ListNode | None, b: ListNode | None) -> ListNode | None:
    dummy = tail = ListNode()
    while a and b:
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a or b
    return dummy.next


def merge_feeds(feeds: list[ListNode | None]) -> ListNode | None:
    # Merge neighbours pairwise, halving the number of feeds each round.
    feeds = list(feeds)
    while len(feeds) > 1:
        merged = [merge_two(feeds[i], feeds[i + 1]) for i in range(0, len(feeds) - 1, 2)]
        if len(feeds) % 2:
            merged.append(feeds[-1])
        feeds = merged
    return feeds[0] if feeds else None

