fn merge_two(mut a: Option<Box<ListNode>>, mut b: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
    let mut out = None;
    let mut tail = &mut out;
    loop {
        let take_a = match (&a, &b) {
            (Some(x), Some(y)) => x.val <= y.val,
            _ => break,
        };
        let src = if take_a { &mut a } else { &mut b };
        let mut node = src.take().unwrap();
        *src = node.next.take();
        tail = &mut tail.insert(node).next;
    }
    *tail = a.or(b);
    out
}

fn merge_feeds(mut feeds: Vec<Option<Box<ListNode>>>) -> Option<Box<ListNode>> {
    // Merge neighbours pairwise, halving the number of feeds each round.
    while feeds.len() > 1 {
        let mut merged = Vec::with_capacity((feeds.len() + 1) / 2);
        let mut it = feeds.into_iter();
        while let Some(a) = it.next() {
            merged.push(match it.next() {
                Some(b) => merge_two(a, b),
                None => a,
            });
        }
        feeds = merged;
    }
    feeds.pop().flatten()
}
